export function toSlug(name) {
  return name.toLowerCase().trim().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-');
}

export function findRecipeBySlug(slug) {
  return recipes.find(r => toSlug(r.name) === slug);
}

